import { addDraft } from './store';
import { sheetContent, toast } from './ui';

/**
 * Offline support. The service worker (generated by vite-plugin-pwa) serves
 * the app from its cache; a new deploy installs in the background and takes
 * over at once. We then reload to show it, unless an entry is in progress.
 */
export function registerServiceWorker(): void {
  if (!('serviceWorker' in navigator) || !import.meta.env.PROD) return;
  const hadController = !!navigator.serviceWorker.controller;
  const started = Date.now();

  navigator.serviceWorker.register('./sw.js').then(reg => {
    // Home-screen apps are resumed rather than relaunched: check on resume too.
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') reg.update().catch(() => {});
    });
  });

  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!hadController) return;
    const busy = !!addDraft.value.amount || !!sheetContent.value;
    if (!busy || Date.now() - started < 3000) location.reload();
    else toast('Nouvelle version disponible', { label: 'Mettre à jour', run: () => location.reload() });
  });
}
